// === Extraer phone del mensaje entrante (descarta status updates) ===
// Soporta doble formato de payload (Meta nativo y traducido).
const raw = $input.first().json;
const body = raw.body || raw;

const entry = body?.entry?.[0];
const changes = entry?.changes?.[0];
const valueMeta = changes?.value;
const value = valueMeta || body;

const messages = value?.messages || value?.mensajes;
const message = messages?.[0];

// Si no hay mensaje real (es un status update u otro evento), no continuar.
if (!message) {
  return [];
}

const phone = message.from || message.de || '';
if (!phone) {
  return [];
}

return [{
  json: {
    phone: String(phone)
  }
}];

